medidas.expresion:
DIVIDE (
    CALCULATE (
        SUM ( v_fleet_normalized[quantity] ),
        v_fleet_normalized[fleet_replacement_status] IN { "Replace Now", "Critical" }
    ),
    [Flota Total]
)

CALCULATE (
    SUM ( v_fleet_transition[variacion] ),
    v_fleet_transition[movimiento] IN { "Entra a la flota", "Crece" }
)

ABS (
    CALCULATE (
        SUM ( v_fleet_transition[variacion] ),
        v_fleet_transition[movimiento] IN { "Sale de la flota", "Se reduce" }
    )
)
